#include <algorithm>
#include <string>
#include <vector>

struct Row { std::string name; std::string team; int hp; };
struct SortSpec { int column; bool ascending; };

static int compareColumn(const Row& a, const Row& b, int column)
{
    switch (column)
    {
    case 0: return a.name < b.name ? -1 : a.name > b.name ? 1 : 0;
    case 1: return a.team < b.team ? -1 : a.team > b.team ? 1 : 0;
    case 2: return a.hp < b.hp ? -1 : a.hp > b.hp ? 1 : 0;
    default: return 0;
    }
}

void sortRows(std::vector<Row>& rows, const std::vector<SortSpec>& specs)
{
    if (specs.empty()) return;
    std::stable_sort(rows.begin(), rows.end(), [&](const Row& a, const Row& b) {
        for (const SortSpec& s : specs)
        {
            const int c{ compareColumn(a, b, s.column) };
            if (c != 0) return s.ascending ? c < 0 : c > 0;
        }
        return false;
    });
}

