std::vector<std::string> names(const std::vector<Row>& r) { std::vector<std::string> n; for (const auto& x : r) n.push_back(x.name); return n; }
std::vector<Row> sample() { return { { "Bat", "red", 5 }, { "Ant", "blue", 9 }, { "Cat", "red", 9 }, { "Dog", "blue", 2 }, { "Eel", "red", 5 } }; }
TEST("by name") { auto r = sample(); sortRows(r, { { 0, true } }); CHECK_EQ(names(r), (std::vector<std::string>{ "Ant", "Bat", "Cat", "Dog", "Eel" })); }
TEST("by hp descending") { auto r = sample(); sortRows(r, { { 2, false } }); CHECK_EQ(names(r), (std::vector<std::string>{ "Ant", "Cat", "Bat", "Eel", "Dog" })); }
TEST("team then hp") { auto r = sample(); sortRows(r, { { 1, true }, { 2, false } }); CHECK_EQ(names(r), (std::vector<std::string>{ "Ant", "Dog", "Cat", "Bat", "Eel" })); }
TEST("ties keep order") { auto r = sample(); sortRows(r, { { 1, false } }); CHECK_EQ(names(r), (std::vector<std::string>{ "Bat", "Cat", "Eel", "Ant", "Dog" })); }
TEST("no specs") { auto r = sample(); sortRows(r, {}); CHECK_EQ(names(r), names(sample())); }

